package com.lexorion.workforce.api;import static com.lexorion.workforce.api.ResourceDtos.*;import com.lexorion.workforce.service.SelfServiceService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/workforce/me")public class SelfServiceController{private final SelfServiceService service;public SelfServiceController(SelfServiceService s){service=s;}@GetMapping public EmployeeResponse me(){return service.me();}@GetMapping("/team")@PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER')")public TeamResponse team(){return service.team();}}
